upportsOrdering&quot;:true},&quot;Validation&quot;:[{&quot;Type&quot;:&quot;required&quot;,&quot;From&quot;:null,&quot;For&quot;:&quot;NameColumn&quot;,&quot;Settings&quot;:{}}],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;TokenizeTokenNames&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Tokenize Token Names&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Token Value always supports Tokens. Check this option to also support Tokens in the Token Name. Usage example: If [Index] has the value of 1, using a Token Name of \&quot;Customer[Index]\&quot; will assign the Token Value to \&quot;Customer1\&quot;.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Boolean&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;RecursionCount&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Number of Recursions&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Specify how many times to apply tokenization. This is useful when tokens contain other tokens that also need to be replaced. Note that this presents a security risk when the expression has content from untrusted users. Supports Tokens.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{&quot;default&quot;:&quot;1&quot;},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[{&quot;Type&quot;:&quot;required&quot;,&quot;From&quot;:null,&quot;For&quot;:null,&quot;Settings&quot;:{}}],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]}],&quot;Output&quot;:[{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;Tokens&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot