    &lt;ActionInfo&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
      &lt;Description&gt;Verifica daca sunt prestatii invalide&lt;/Description&gt;
      &lt;ActionType&gt;ExecuteActions&lt;/ActionType&gt;
      &lt;OrderIndex&gt;1&lt;/OrderIndex&gt;
      &lt;LastModified&gt;2026-03-20T14:48:03.613&lt;/LastModified&gt;
      &lt;LastModifiedBy&gt;5&lt;/LastModifiedBy&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Id&quot;:-1,&quot;$_uid&quot;:&quot;action1773926053752168&quot;,&quot;EventName&quot;:&quot;click&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH Parametri AS (\n    SELECT [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV], Luna = [GetOrSession:MonthV])] AS ZileLucratoare\n),\nInfoSalariat AS (\n    SELECT \n        a.Marca, \n        -- Calculăm zilele lucrate efectiv scăz&#226;nd concediile din norma lunii\n        (p.ZileLucratoare - ISNULL(co.ZileCOLuna, 0) - ISNULL(cm.ZileCMLuna, 0)) AS ZileLucrate\n    FROM app.Salariat a\n    CROSS JOIN Parametri p\n    \n    -- Calculăm CO din intervalele 1, 2 și 3 pentru luna/anul selectat\n    OUTER APPLY (\n        SELECT SUM(ISNULL(NrZileCO1,0) + ISNULL(NrZileCO2,0) + ISNULL(NrZileCO3,0)) AS ZileCOLuna\n        FROM app.ConcediudeOdihna\n        WHERE Marca = a.Marca \n          AND CodSucursala = a.CodSucursala\n          AND Anul = @Anul \n          AND Luna = @Luna\n    ) co\n\n    -- Calculăm CM din zilele lucrătoare de plată\n    OUTER APPLY (\n        SELECT SUM(ISNULL(TotZileLucratoare, 0)) AS ZileCMLuna\n        FROM app.ConcediuMedical\n        WHERE Marca = a.Marca \n          AND CodSucursala = a.CodSucursala\n          AND AnuldePlata = @Anul \n          AND LunadePlata = @Luna\n    ) cm\n\n    WHERE a.Marca = @MarcaIntroduse \n      AND a.Anul = @Anul \n      AND a.Luna = @Luna \n      AND a.CodSucursala = @CodSucursala\n)\n-- Dacă ZileLucrate e 0 sau negativ, &#238;nseamnă că luna e deja \&quot;plină\&quot; cu CO/CM\nSELECT COUNT(*) AS EsteInvalid \nFROM InfoSalariat \nWHERE ZileLucrate &amp;lt;= 0&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;},{&quot;value&quot;:&quot;[p_Marca]&quot;,&quot;name&quot;:&quot;MarcaIntroduse&quot;}],&quot;OutputTokenName&quot;:&quot;EsteInvalid&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;Definition&quot;:{&quot;IsClientAction&quot;:false,&quot;Settings&quot;:{&quot;Group&quot;:&quot;Data&quot;,&quot;FeatureFlag&quot;:&quot;Standard.DataIntegration&quot;}}},{&quot;Id&quot;:-1,&quot;$_uid&quot;:&quot;action17739260537527156&quot;,&quot;EventName&quot;:&quot;click&quot;,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Atenție! Agentul [p_Marca] are 0 zile lucrate &#238;n această lună. Prestația a fost adăugată, dar va apărea &#238;n lista de invalide.&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;BgColor&quot;:&quot;&quot;,&quot;Transition&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;fade&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:&quot;&quot;,&quot;HideTime&quot;:&quot;5000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;TextAlignment&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;center&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;ShowLoader&quot;:&quot;&quot;,&quot;LoaderColor&quot;:&quot;&quot;},&quot;ActionType&quot;:&quot;ShowToastAndContinue&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;Definition&quot;:{&quot;IsClientAction&quot;:false,&quot;Settings&quot;:{&quot;Group&quot;:&quot;Message&quot;,&quot;IsFlushableAction&quot;:&quot;true&quot;}},&quot;Condition&quot;:&quot;[EsteInvalid] &amp;gt; 0&quot;},{&quot;Id&quot;:-1,&quot;$_uid&quot;:&quot;action17739260537529802&quot;,&quot;EventName&quot;:&quot;click&quot;,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;a7612098-9971-4e9d-898e-9341e2b935a9&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}}},&quot;ActionType&quot;:&quot;RefreshGrid&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;Definition&quot;:{&quot;IsClientAction&quot;:false,&quot;Settings&quot;:{&quot;Group&quot;:&quot;UI Actions&quot;,&quot;JavaScriptFile&quot;:&quot;Common/static/client-actions/RefreshGrid.js&quot;}}}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
