    &lt;ActionInfo&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
      &lt;Description&gt;Verifica daca sunt prestatii invalide&lt;/Description&gt;
      &lt;ActionType&gt;ExecuteActions&lt;/ActionType&gt;
      &lt;OrderIndex&gt;5&lt;/OrderIndex&gt;
      &lt;LastModified&gt;2026-03-20T14:48:03.677&lt;/LastModified&gt;
      &lt;LastModifiedBy&gt;5&lt;/LastModifiedBy&gt;
      &lt;ActionData&gt;{&quot;ActionList&quot;:[{&quot;Id&quot;:-1,&quot;$_uid&quot;:&quot;action1773926110967125&quot;,&quot;EventName&quot;:&quot;click&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH Parametri AS (\n    SELECT [Initializari:ZileLucratoare_old(Anul = [GetOrSession:YearV],Luna = [GetOrSession:MonthV])] AS ZileLucratoare\n),\nExceptiiLichidate AS (\n    SELECT a.Marca, a.CodSucursala\n    FROM app.Salariat a\n    CROSS JOIN Parametri p\n    OUTER APPLY (\n        SELECT SUM(\n            CASE WHEN c.Interval1DatadeInceput IS NOT NULL AND MONTH(c.Interval1DatadeInceput) = @Luna AND YEAR(c.Interval1DatadeInceput) = @Anul THEN ISNULL(c.NrZileCO1, 0) ELSE 0 END + \n            CASE WHEN c.Interval2DatadeInceput IS NOT NULL AND MONTH(c.Interval2DatadeInceput) = @Luna AND YEAR(c.Interval2DatadeInceput) = @Anul THEN ISNULL(c.NrZileCO2, 0) ELSE 0 END + \n            CASE WHEN c.Interval3DatadeInceput IS NOT NULL AND MONTH(c.Interval3DatadeInceput) = @Luna AND YEAR(c.Interval3DatadeInceput) = @Anul THEN ISNULL(c.NrZileCO3, 0) ELSE 0 END\n        ) AS ZileCOLuna\n        FROM app.ConcediudeOdihna c\n        WHERE c.Marca = a.Marca AND c.CodSucursala = a.CodSucursala AND c.CodSucursala = @CodSucursala\n    ) co\n    OUTER APPLY (\n        SELECT SUM(m.TotZileLucratoare) AS ZileCMLuna\n        FROM app.ConcediuMedical m\n        WHERE m.Marca = a.Marca AND m.CodSucursala = @CodSucursala AND m.AnulDePlata = @Anul AND m.LunaDePlata = @Luna\n    ) cm\n    CROSS APPLY (\n        SELECT CASE WHEN p.ZileLucratoare - ISNULL(co.ZileCOLuna, 0) - ISNULL(cm.ZileCMLuna, 0) &amp;lt;= 0 THEN 0 ELSE p.ZileLucratoare - ISNULL(co.ZileCOLuna, 0) - ISNULL(cm.ZileCMLuna, 0) END AS ZileLucrate\n    ) zl\n    WHERE zl.ZileLucrate = 0 AND a.Anul = @Anul AND a.Luna = @Luna AND a.CodSucursala = @CodSucursala\n)\nSELECT COUNT(DISTINCT ex.Marca) AS NumarImpostori\nFROM ExceptiiLichidate ex\nINNER JOIN app.Agent ag \n    ON ex.Marca = ag.Marca AND ex.CodSucursala = ag.CodSucursala AND ag.Anul = @Anul AND ag.Luna = @Luna;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;NrImpostori&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;Definition&quot;:{&quot;IsClientAction&quot;:false,&quot;Settings&quot;:{&quot;Group&quot;:&quot;Data&quot;,&quot;FeatureFlag&quot;:&quot;Standard.DataIntegration&quot;}}},{&quot;Id&quot;:-1,&quot;$_uid&quot;:&quot;action17739261109678594&quot;,&quot;EventName&quot;:&quot;click&quot;,&quot;Parameters&quot;:{&quot;Heading&quot;:&quot;&quot;,&quot;Message&quot;:&quot;&amp;lt;p&amp;gt;Atenție! Au fost adăugate prestații pentru [NrImpostori] agent/agenți care nu au nicio zi lucrată &#238;n această lună. Te rugăm să verifici lista de excepții!&amp;lt;/p&amp;gt;&quot;,&quot;Icon&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;warning&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;BgColor&quot;:&quot;&quot;,&quot;Transition&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;fade&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;AllowToastClose&quot;:true,&quot;CallBackJsCode&quot;:&quot;&quot;,&quot;HideTime&quot;:&quot;3000&quot;,&quot;Stack&quot;:&quot;1&quot;,&quot;ToastPosition&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;mid-center&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;TextAlignment&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;center&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}},&quot;ShowLoader&quot;:&quot;&quot;,&quot;LoaderColor&quot;:&quot;&quot;},&quot;ActionType&quot;:&quot;ShowToastAndContinue&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;Definition&quot;:{&quot;IsClientAction&quot;:false,&quot;Settings&quot;:{&quot;Group&quot;:&quot;Message&quot;,&quot;IsFlushableAction&quot;:&quot;true&quot;}},&quot;Condition&quot;:&quot;[NrImpostori] &amp;gt; 0&quot;},{&quot;Id&quot;:-1,&quot;$_uid&quot;:&quot;action17739261109675547&quot;,&quot;EventName&quot;:&quot;click&quot;,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;a7612098-9971-4e9d-898e-9341e2b935a9&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}}},&quot;ActionType&quot;:&quot;RefreshGrid&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;Definition&quot;:{&quot;IsClientAction&quot;:false,&quot;Settings&quot;:{&quot;Group&quot;:&quot;UI Actions&quot;,&quot;JavaScriptFile&quot;:&quot;Common/static/client-actions/RefreshGrid.js&quot;}}}],&quot;OnError&quot;:[]}&lt;/ActionData&gt;
      &lt;ModuleId&gt;865&lt;/ModuleId&gt;
